def find(items, name):
    """Return the item called `name`, or None."""
    for item in items:
        if item["name"] == name:
            return item
    return None


def low_stock(items):
    """Return names of items below the configured low-stock threshold, alphabetically."""
    threshold = int(settings.get("LOW_STOCK_THRESHOLD", 12))
    return sorted(item["name"] for item in items if item["quantity"] < threshold)

